// Pull a quote from the user's own library (reviews, notes, summaries)
export function getUserQuote(books = [], articles = []) {
  const sources = [...books, ...articles];
  const candidates = [];
  sources.forEach(b => {
    if (b.review && b.review.trim().length > 20) {
      candidates.push({
        text: b.review.trim(),
        attribution: `Your note on ${b.title}`
      });
    }
    if (b.notes && b.notes.trim().length > 20) {
      candidates.push({
        text: b.notes.trim(),
        attribution: `Margin note — ${b.title}`
      });
    }
    if (b.summary && b.summary.trim().length > 20) {
      candidates.push({
        text: b.summary.trim(),
        attribution: `Your summary of ${b.title}`
      });
    }
  });
  return candidates.length > 0 ? candidates : null;
}

// Pick a quote for the day (deterministic by date so it doesn't flicker)
export function getDailyQuote(books = [], articles = []) {
  const dayIndex = Math.floor(Date.now() / 86400000); // changes daily
  const userQuotes = getUserQuote(books, articles);
  const pool = userQuotes ? [...ARCHIVIST_QUOTES, ...userQuotes, ...userQuotes] // weight user quotes 2x
  : ARCHIVIST_QUOTES;
  return pool[dayIndex % pool.length];
}

// Pick a random quote for empty states
export function getEmptyStateQuote(books = [], articles = []) {
  const userQuotes = getUserQuote(books, articles);
  const pool = userQuotes ? [...ARCHIVIST_QUOTES, ...userQuotes] : ARCHIVIST_QUOTES;
  const i = Math.floor(Math.random() * pool.length);
  return pool[i];
}

